), aplicado AS (
  UPDATE trips t
     SET evidence_window_start = n.inicio, evidence_window_end = n.fin
    FROM nuevas n
   WHERE t.id = n.id
     AND t.evidence_status = 'en_espera'
     AND NOT EXISTS (SELECT 1 FROM evidence_points ep WHERE ep.trip_id = t.id)
     AND NOT EXISTS (
       SELECT 1 FROM compliance_facts cf
        WHERE cf.service_occurrence_id = t.service_occurrence_id)
  RETURNING t.id
)
SELECT count(*) AS viajes_movidos FROM aplicado;  -- se esperan 738

-- 2 · Verificación. Los TRES números, no solo el de los errores:
--     encontrados  = 738   (si es 0, la lista no casó con nada)
--     con_la_nueva = 738
--     sin_mover    = 0
--
--     'sin_mover = 0' por sí solo NO prueba nada: da 0 igual si todos
--     se movieron que si el JOIN no encontró ni un viaje. Es el mismo
--     cero ciego que el cron contesta con 503 en vez de «todo bien».
SELECT count(*) AS encontrados,
       count(*) FILTER (WHERE t.evidence_window_start = n.inicio) AS con_la_nueva,
       count(*) FILTER (WHERE t.evidence_window_start IS DISTINCT FROM n.inicio) AS sin_mover
  FROM trips t
  JOIN (VALUES
